    /**
     * Extracts and materializes all concrete Java and React code blocks from IMPLEMENTATION_SUMMARY.md onto disk.
     */
    public void extractAndMaterializeCodeBlocks(Path projectBase) {
        try {
            Path summaryPath = projectBase.resolve("src/IMPLEMENTATION_SUMMARY.md");
            if (!Files.exists(summaryPath)) return;
            String markdown = Files.readString(summaryPath);

            // 1. Materialize Java classes, interfaces, records
            Pattern javaPattern = Pattern.compile("```java\\s*\\n(package\\s+([a-zA-Z0-9_.]+);[\\s\\S]*?)\\n```");
            Matcher javaMatcher = javaPattern.matcher(markdown);

            Path javaBase = projectBase.resolve("src/backend/src/main/java");

            while (javaMatcher.find()) {
                String code = javaMatcher.group(1).trim();
                String pkg = javaMatcher.group(2).trim();

                Matcher classMatcher = Pattern.compile("(?:public\\s+)?(?:final\\s+)?(?:class|interface|record|enum)\\s+([a-zA-Z0-9_]+)").matcher(code);
                if (classMatcher.find()) {
                    String className = classMatcher.group(1);
                    Path targetDir = javaBase.resolve(pkg.replace(".", "/"));
                    Files.createDirectories(targetDir);
                    Path targetFile = targetDir.resolve(className + ".java");
                    Files.writeString(targetFile, code + "\n");
                    log.info("Materialized domain code block from LLM: {}/{}", pkg, className);
                }
            }

            // 2. Materialize TSX/React page if emitted by LLM
            Pattern tsxPattern = Pattern.compile("```(?:tsx|typescript)\\s*\\n([\\s\\S]*?export\\s+default\\s+function[\\s\\S]*?)\\n```");
            Matcher tsxMatcher = tsxPattern.matcher(markdown);
            if (tsxMatcher.find()) {
                String tsxCode = tsxMatcher.group(1).trim();
                Path fePage = projectBase.resolve("src/frontend/app/page.tsx");
                Files.createDirectories(fePage.getParent());
                Files.writeString(fePage, tsxCode + "\n");
                log.info("Materialized frontend page.tsx from LLM inference block for project: {}", projectBase.getFileName());
            }
        } catch (Exception ex) {
            log.warn("Notice during code block materialization for project {}: {}", projectBase.getFileName(), ex.getMessage());
        }
    }

    /**
     * Extracts and materializes concrete unit test suites from TDD_PLAN_AND_SPECS.md onto disk.
     */
    public int materializeTddTestBlocks(Path projectBase) {
        int count = 0;
        try {
            Path planPath = projectBase.resolve("tests/TDD_PLAN_AND_SPECS.md");
            if (!Files.exists(planPath)) return 0;
            String markdown = Files.readString(planPath);

            Pattern testPattern = Pattern.compile("```java\\s*\\n(package\\s+([a-zA-Z0-9_.]+);[\\s\\S]*?)\\n```");
            Matcher matcher = testPattern.matcher(markdown);

            Path backendTestSrc = projectBase.resolve("src/backend/src/test/java");
            Path testsBackendDir = projectBase.resolve("tests/backend");

            while (matcher.find()) {
                String code = matcher.group(1).trim();
                String pkg = matcher.group(2).trim();

                Matcher classMatcher = Pattern.compile("(?:public\\s+)?(?:final\\s+)?class\\s+([a-zA-Z0-9_]+Test)").matcher(code);
                if (classMatcher.find()) {
                    String className = classMatcher.group(1);
                    Path targetSrcDir = backendTestSrc.resolve(pkg.replace(".", "/"));
                    Files.createDirectories(targetSrcDir);
                    Files.writeString(targetSrcDir.resolve(className + ".java"), code + "\n");

                    Files.createDirectories(testsBackendDir);
                    Files.writeString(testsBackendDir.resolve(className + ".java"), code + "\n");

                    count++;
                    log.info("Materialized TDD test class from LLM: {}/{}", pkg, className);
                }
            }
        } catch (Exception ex) {
            log.warn("Notice during TDD test materialization for project {}: {}", projectBase.getFileName(), ex.getMessage());
        }
        return count;
    }

    private void scaffoldFallbackTestBaseline(Path projectBase, DomainProfile profile) {
        try {
            Path backendTestSrc = projectBase.resolve("src/backend/src/test/java/" + profile.packageDir() + "/domain");
            Files.createDirectories(backendTestSrc);
            Path testFile = backendTestSrc.resolve(profile.primaryEntityName() + "BaselineTest.java");
            Files.writeString(testFile, String.format("""
package %s.domain;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

@DisplayName("%s TDD Baseline Contract")
class %sBaselineTest {

    @Test
    @DisplayName("Verify platform baseline test harness initialization")
    void verifyBaselineHarness() {
        assertThat(true).isTrue();
    }
}
""", profile.packageName(), profile.primaryEntityName(), profile.primaryEntityName()));

            Path testsBackendDir = projectBase.resolve("tests/backend");
            Files.createDirectories(testsBackendDir);
            Files.writeString(testsBackendDir.resolve(profile.primaryEntityName() + "BaselineTest.java"),
                    Files.readString(testFile));
        } catch (Exception e) {
            log.warn("Notice writing fallback baseline test: {}", e.getMessage());
        }
    }

    // =========================================================================
    // Dynamic Entity & Domain Extraction Helpers (SSOT from Artifacts - UNTOUCHED)
    // =========================================================================

    private String discoverPrimaryEntity(String c4Model, String sqlSchema, String implSummary, String taskName) {
        // Priority 1: Check C4 Model for DDD Aggregate Root
        if (c4Model != null && !c4Model.isBlank()) {
            Matcher m = Pattern.compile("(?:Aggregate Root|Aggregate|Primary Entity)[:\\s*`]+([A-Z][a-zA-Z0-9]+)").matcher(c4Model);
            if (m.find()) {
                return m.group(1).trim();
            }
            Matcher mermaidMatcher = Pattern.compile("Agg_\\w+\\[\"([A-Z][a-zA-Z0-9]+)\\s+Aggregate").matcher(c4Model);
            if (mermaidMatcher.find()) {
                return mermaidMatcher.group(1).trim();
            }
        }

        // Priority 2: Check Database Schema DDL for business tables
        if (sqlSchema != null && !sqlSchema.isBlank()) {
            Matcher tableMatcher = Pattern.compile("CREATE\\s+TABLE\\s+(?:IF\\s+NOT\\s+EXISTS\\s+)?(?:[a-zA-Z0-9_]+\\.)?([a-zA-Z0-9_]+)", Pattern.CASE_INSENSITIVE).matcher(sqlSchema);
            Set<String> infraTables = Set.of("users", "user_sessions", "sessions", "audit_logs", "audits", "flyway_schema_history", "schema_migrations");
            List<String> tables = new ArrayList<>();
            while (tableMatcher.find()) {
                String tbl = tableMatcher.group(1).toLowerCase();
                if (!infraTables.contains(tbl)) {
                    tables.add(tbl);
                }
            }
            if (!tables.isEmpty()) {
                return snakeToPascal(tables.get(0));
            }
        }

        // Priority 3: Check Implementation Summary for Java classes
        if (implSummary != null && !implSummary.isBlank()) {
            Matcher classMatcher = Pattern.compile("public\\s+(?:final\\s+)?(?:class|record)\\s+([A-Z][a-zA-Z0-9]+)").matcher(implSummary);
            Set<String> skipClasses = Set.of("Application", "TenantContextHolder", "DomainInvariantViolationException", "UnauthorizedException", "ProblemDetail");
            while (classMatcher.find()) {
                String candidate = classMatcher.group(1);
                if (!skipClasses.contains(candidate) && !candidate.endsWith("Test") && !candidate.endsWith("Exception") && !candidate.endsWith("Config")) {
                    return candidate;
                }
            }
        }

        // Priority 4: Dynamic noun extraction from task name
        return extractNounFromTask(taskName);
    }

    private String discoverSecondaryEntity(String c4Model, String sqlSchema, String implSummary, String primaryEntity) {
        // Priority 1: Check C4 Model
        if (c4Model != null && !c4Model.isBlank()) {
            Matcher m = Pattern.compile("(?:Aggregate Root|Aggregate|Entity)[:\\s*`]+([A-Z][a-zA-Z0-9]+)").matcher(c4Model);
            while (m.find()) {
                String name = m.group(1).trim();
                if (!name.equalsIgnoreCase(primaryEntity)) {
                    return name;
                }
            }
            Matcher mermaidMatcher = Pattern.compile("Agg_\\w+\\[\"([A-Z][a-zA-Z0-9]+)\\s+Aggregate").matcher(c4Model);
            while (mermaidMatcher.find()) {
                String name = mermaidMatcher.group(1).trim();
                if (!name.equalsIgnoreCase(primaryEntity)) {
                    return name;
                }
            }
        }

        // Priority 2: Check SQL Schema for 2nd non-infra table
        if (sqlSchema != null && !sqlSchema.isBlank()) {
            Matcher tableMatcher = Pattern.compile("CREATE\\s+TABLE\\s+(?:IF\\s+NOT\\s+EXISTS\\s+)?(?:[a-zA-Z0-9_]+\\.)?([a-zA-Z0-9_]+)", Pattern.CASE_INSENSITIVE).matcher(sqlSchema);
            Set<String> infraTables = Set.of("users", "user_sessions", "sessions", "audit_logs", "audits", "flyway_schema_history", "schema_migrations");
            while (tableMatcher.find()) {
                String tbl = tableMatcher.group(1).toLowerCase();
                if (!infraTables.contains(tbl)) {
                    String candidate = snakeToPascal(tbl);
                    if (!candidate.equalsIgnoreCase(primaryEntity)) {
                        return candidate;
                    }
                }
            }
        }

        return primaryEntity + "Record";
    }

    private String discoverPackageName(String implSummary, String projectId) {
        if (implSummary != null && !implSummary.isBlank()) {
            Matcher m = Pattern.compile("package\\s+([a-zA-Z0-9_.]+);").matcher(implSummary);
            if (m.find()) {
                String fullPkg = m.group(1).trim();
                String[] parts = fullPkg.split("\\.");
                if (parts.length >= 3) {
                    return parts[0] + "." + parts[1] + "." + parts[2];
                }
                return fullPkg;
            }
        }
        String cleanId = projectId != null ? projectId.toLowerCase().replaceAll("[^a-z0-9]", "") : "app";
        return "com.agentic." + (cleanId.isBlank() ? "app" : cleanId);
    }

    private String snakeToPascal(String snake) {
        if (snake == null || snake.isBlank()) return "Item";
        StringBuilder sb = new StringBuilder();
        String[] parts = snake.split("_");
        for (String part : parts) {
            if (!part.isBlank()) {
                sb.append(Character.toUpperCase(part.charAt(0)));
                if (part.length() > 1) {
                    sb.append(part.substring(1).toLowerCase());
                }
            }
        }
        String result = sb.toString();
        // Singularization
        if (result.endsWith("ies") && result.length() > 3) {
            result = result.substring(0, result.length() - 3) + "y";
        } else if ((result.endsWith("ches") || result.endsWith("shes") || result.endsWith("sses") || result.endsWith("xes") || result.endsWith("zes")) && result.length() > 4) {
            result = result.substring(0, result.length() - 2);
        } else if (result.endsWith("s") && !result.endsWith("ss") && result.length() > 1) {
            result = result.substring(0, result.length() - 1);
        }
        return result.isBlank() ? "Item" : result;
    }

    private String extractNounFromTask(String taskName) {
        if (taskName == null || taskName.isBlank()) return "Domain";
        Set<String> stopWords = Set.of(
                "a", "an", "the", "and", "or", "for", "with", "to", "in", "on", "at",
                "create", "build", "develop", "implement", "app", "apps", "application",
                "platform", "system", "service", "portal", "tool", "website"
        );
        String[] words = taskName.replaceAll("[^a-zA-Z0-9\\s]", " ").trim().split("\\s+");
        StringBuilder sb = new StringBuilder();
        for (String w : words) {
            String lower = w.toLowerCase();
            if (!stopWords.contains(lower) && !w.isBlank()) {
                sb.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1).toLowerCase());
                if (sb.length() >= 15) break;
            }
        }
        String candidate = sb.toString();
        return candidate.isBlank() ? "Domain" : candidate;
    }

    private String deriveProjectSlug(String projectId, String taskName) {
        if (taskName != null && !taskName.isBlank()) {
            String s = taskName.toLowerCase().replaceAll("[^a-z0-9\\s-]", "").trim().replaceAll("\\s+", "-");
            if (s.length() > 25) {
                s = s.substring(0, 25).replaceAll("-+$", "");
            }
            if (!s.isBlank()) return s;
        }
        return (projectId != null ? projectId.toLowerCase().replaceAll("[^a-z0-9]", "-") : "app").replaceAll("-+", "-");
    }

    private String toPascalCase(String slug) {
        if (slug == null || slug.isBlank()) return "App";
        StringBuilder sb = new StringBuilder();
        for (String part : slug.split("-")) {
            if (!part.isBlank()) {
                sb.append(Character.toUpperCase(part.charAt(0)));
                if (part.length() > 1) {
                    sb.append(part.substring(1).toLowerCase());
                }
            }
        }
        return sb.toString().isBlank() ? "App" : sb.toString();
    }

